    const available = state.stock[event.item] ?? 0;
    if (available >= (event.qty as number)) {
      state.stock[event.item] = available - (event.qty as number);
      state.reserved[event.id] = { item: event.item, qty: event.qty as number };
      state.orders[event.id] = "reserved";
    } else {
      state.queue.push(event.id);
      state.pendingWants[event.id] = { item: event.item, qty: event.qty as number };
      state.orders[event.id] = "backordered";
    }
    return null;
  },
  cancel: (state, event) => {
    if (typeof event.id !== "string" || event.id.length === 0) return "bad id";
    if (state.reserved[event.id] !== undefined) {
      const holding = state.reserved[event.id];
      state.stock[holding.item] = (state.stock[holding.item] ?? 0) + holding.qty;
      delete state.reserved[event.id];
      state.orders[event.id] = "cancelled";
      fillPending(state);
    } else if (state.orders[event.id] === "backordered") {
      state.queue.splice(state.queue.indexOf(event.id), 1);
      delete state.pendingWants[event.id];
      state.orders[event.id] = "cancelled";
    } else {
      state.rejected = state.rejected + 1;
    }
    return null;
  },
  ship: (state, event) => {
    if (typeof event.id !== "string" || event.id.length === 0) return "bad id";
    if (
      event.qty !== undefined &&
      (!Number.isInteger(event.qty) || (event.qty as number) < 1)
    ) {
      return "bad qty";
    }
    const holding = state.reserved[event.id];
    if (holding === undefined) {
      state.rejected = state.rejected + 1;
    } else if (event.qty === undefined || (event.qty as number) === holding.qty) {
      delete state.reserved[event.id];
      state.orders[event.id] = "shipped";
    } else if ((event.qty as number) < holding.qty) {
      state.reserved[event.id].qty = holding.qty - (event.qty as number);
      state.orders[event.id] = "partial";
    } else {
      state.rejected = state.rejected + 1;
    }
    return null;
  },
  restock: (state, event) => {
    if (typeof event.item !== "string" || event.item.length === 0) return "bad item";
    if (!Number.isInteger(event.qty) || (event.qty as number) < 1) return "bad qty";
    state.stock[event.item] = (state.stock[event.item] ?? 0) + (event.qty as number);
    fillPending(state);
    return null;
  },
  expire: (state, event) => {
    if (typeof event.id !== "string" || event.id.length === 0) return "bad id";
    if (state.reserved[event.id] !== undefined) {
      const holding = state.reserved[event.id];
      state.stock[holding.item] = (state.stock[holding.item] ?? 0) + holding.qty;
      delete state.reserved[event.id];
      state.orders[event.id] = "expired";
      fillPending(state);
    } else {
      state.rejected = state.rejected + 1;
    }
    return null;
  },
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: State = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Record<string, unknown>;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: "event " + index + ": malformed" };
    }
    const handle = HANDLERS[event.type as string];
    if (handle === undefined) {
      return { ok: false, error: "event " + index + ": bad type" };
    }
    const trouble = handle(state, event);
    if (trouble !== null) {
      return { ok: false, error: "event " + index + ": " + trouble };
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}
